INSERT INTO public_support (id,slug,title,summary,category,tags,heading,sections,related_articles,updated_at,environment,display_order) VALUES ('recognise-phishing','recognise-phishing','How to recognise a phishing attempt','Avoiding scams','SECURITY',ARRAY['avoiding scams','insight']::text[],'How to recognise a phishing attempt','[{"heading":"What to know","paragraphs":["Be cautious of urgency, unfamiliar links and requests for security codes.","Open your bank through a known bookmark or its official app. Verify unexpected contact using a trusted channel."],"callouts":["Never disclose passwords, PINs or one-time security codes."]}]'::jsonb,ARRAY['lost-card','pending-card-payments']::text[],'2026-09-27T09:00:00+08:00','DEMO',0) ON CONFLICT DO NOTHING;
INSERT INTO public_support (id,slug,title,summary,category,tags,heading,sections,related_articles,updated_at,environment,display_order) VALUES ('lost-card','lost-card','What to do if your card is lost','Lost card help','CARDS',ARRAY['lost card help','guide']::text[],'What to do if your card is lost','[{"heading":"What to know","paragraphs":["Act promptly when a card is missing or you notice unfamiliar activity.","Contact your card issuer through a trusted channel and follow its instructions for blocking the card. Review recent activity."],"callouts":["This public demo cannot freeze a real card or report a loss."]}]'::jsonb,ARRAY['pending-card-payments','bank-transfers']::text[],'2026-09-27T09:00:00+08:00','DEMO',1) ON CONFLICT DO NOTHING;
INSERT INTO public_support (id,slug,title,summary,category,tags,heading,sections,related_articles,updated_at,environment,display_order) VALUES ('pending-card-payments','pending-card-payments','Understanding pending card payments','Pending payments','CARDS',ARRAY['pending payments','guide']::text[],'Understanding pending card payments','[{"heading":"What to know","paragraphs":["A card authorisation may reserve funds before the merchant completes settlement.","A pending debit can reduce available funds while the booked balance remains unchanged. Release and settlement timing depends on the issuer and merchant."],"callouts":["Do not assume a pending payment has failed or repeat it automatically."]}]'::jsonb,ARRAY['bank-transfers','failed-transfer']::text[],'2026-09-27T09:00:00+08:00','DEMO',2) ON CONFLICT DO NOTHING;
INSERT INTO public_support (id,slug,title,summary,category,tags,heading,sections,related_articles,updated_at,environment,display_order) VALUES ('bank-transfers','bank-transfers','How bank transfers work','Transfers explained','PAYMENTS',ARRAY['transfers explained','guide']::text[],'How bank transfers work','[{"heading":"What to know","paragraphs":["Transfers move funds using recipient and account details.","Check the recipient, currency and amount before confirming. Settlement time depends on the payment route and processing schedule."],"callouts":["This article does not execute or guarantee a transfer."]}]'::jsonb,ARRAY['failed-transfer','balance-available']::text[],'2026-09-27T09:00:00+08:00','DEMO',3) ON CONFLICT DO NOTHING;
INSERT INTO public_support (id,slug,title,summary,category,tags,heading,sections,related_articles,updated_at,environment,display_order) VALUES ('failed-transfer','failed-transfer','Why a transfer may fail','Transfer troubleshooting','PAYMENTS',ARRAY['transfer troubleshooting','guide']::text[],'Why a transfer may fail','[{"heading":"What to know","paragraphs":["Incorrect recipient details, restrictions or insufficient available funds can prevent a transfer.","Review the reported reason and payment status before attempting another transfer. Use a trusted support channel if the outcome is unclear."],"callouts":["Avoid duplicate payments when an earlier result is uncertain."]}]'::jsonb,ARRAY['balance-available','recurring-payments']::text[],'2026-09-27T09:00:00+08:00','DEMO',4) ON CONFLICT DO NOTHING;
INSERT INTO public_support (id,slug,title,summary,category,tags,heading,sections,related_articles,updated_at,environment,display_order) VALUES ('balance-available','balance-available','Balance and available balance','Understanding account balances','ACCOUNTS',ARRAY['understanding account balances','guide']::text[],'Balance and available balance','[{"heading":"What to know","paragraphs":["Balance records booked funds; available balance reflects funds currently usable.","For the demo current account, pending debit holds reduce available balance. Other banking products may use different rules."],"callouts":["Pending amounts are not always booked transactions."]}]'::jsonb,ARRAY['recurring-payments','step-up-verification']::text[],'2026-09-27T09:00:00+08:00','DEMO',5) ON CONFLICT DO NOTHING;
INSERT INTO public_support (id,slug,title,summary,category,tags,heading,sections,related_articles,updated_at,environment,display_order) VALUES ('recurring-payments','recurring-payments','How recurring payments work','Recurring payments','PAYMENTS',ARRAY['recurring payments','guide']::text[],'How recurring payments work','[{"heading":"What to know","paragraphs":["A recurring arrangement describes future scheduled collections or payments.","Review the schedule, amount and beneficiary. Stopping an arrangement may not cancel a payment already in progress."],"callouts":["Contact the service provider about any separate contract."]}]'::jsonb,ARRAY['step-up-verification','investment-risk']::text[],'2026-09-27T09:00:00+08:00','DEMO',6) ON CONFLICT DO NOTHING;
INSERT INTO public_support (id,slug,title,summary,category,tags,heading,sections,related_articles,updated_at,environment,display_order) VALUES ('step-up-verification','step-up-verification','What step-up verification means','Extra verification','SECURITY',ARRAY['extra verification','guide']::text[],'What step-up verification means','[{"heading":"What to know","paragraphs":["Some sensitive actions require stronger verification than the initial sign-in.","An authorisation should be tied to the particular action and expire after a short period. Verify the action details before approving it."],"callouts":["Never share a verification code with someone who contacts you."]}]'::jsonb,ARRAY['investment-risk','budgeting-basics']::text[],'2026-09-27T09:00:00+08:00','DEMO',7) ON CONFLICT DO NOTHING;
INSERT INTO public_support (id,slug,title,summary,category,tags,heading,sections,related_articles,updated_at,environment,display_order) VALUES ('investment-risk','investment-risk','Understanding investment risk levels','Investment risk','INVESTMENTS',ARRAY['investment risk','guide']::text[],'Understanding investment risk levels','[{"heading":"What to know","paragraphs":["Risk depends on market exposure, liquidity, credit quality and your investment horizon.","A risk label summarises selected characteristics. It cannot predict losses or guarantee that a product is suitable for you."],"callouts":["Investments can lose value. This is general education, not personal advice."]}]'::jsonb,ARRAY['budgeting-basics','bond-risk']::text[],'2026-09-27T09:00:00+08:00','DEMO',8) ON CONFLICT DO NOTHING;
INSERT INTO public_support (id,slug,title,summary,category,tags,heading,sections,related_articles,updated_at,environment,display_order) VALUES ('budgeting-basics','budgeting-basics','Budgeting basics','Building a spending plan','ACCOUNTS',ARRAY['building a spending plan','insight']::text[],'Budgeting basics','[{"heading":"What to know","paragraphs":["Start with income, essential costs and a manageable savings target.","Review spending categories regularly and leave room for irregular costs. Use estimates as a starting point and adjust them as circumstances change."],"callouts":["A budget is a planning aid, not a promise about future finances."]}]'::jsonb,ARRAY['bond-risk','exchange-rates']::text[],'2026-09-27T09:00:00+08:00','DEMO',9) ON CONFLICT DO NOTHING;
INSERT INTO public_support (id,slug,title,summary,category,tags,heading,sections,related_articles,updated_at,environment,display_order) VALUES ('bond-risk','bond-risk','Understanding bond risk','Bond investing','INVESTMENTS',ARRAY['bond investing','insight']::text[],'Understanding bond risk','[{"heading":"What to know","paragraphs":["Bond values respond to interest rates, issuer credit quality and liquidity.","A longer maturity can increase interest-rate sensitivity. A higher quoted yield may reflect greater risk."],"callouts":["Bonds and bond funds can lose capital."]}]'::jsonb,ARRAY['exchange-rates','online-banking']::text[],'2026-09-27T09:00:00+08:00','DEMO',10) ON CONFLICT DO NOTHING;
INSERT INTO public_support (id,slug,title,summary,category,tags,heading,sections,related_articles,updated_at,environment,display_order) VALUES ('exchange-rates','exchange-rates','How exchange rates work','Foreign exchange rates','ACCOUNTS',ARRAY['foreign exchange rates','insight']::text[],'How exchange rates work','[{"heading":"What to know","paragraphs":["An exchange rate expresses one currency in units of another.","Compare the quoted rate, markup and any fixed fee. An indicative rate may differ from the final executable quote."],"callouts":["All rates on this website are illustrative demo values."]}]'::jsonb,ARRAY['online-banking','account-statements']::text[],'2026-09-27T09:00:00+08:00','DEMO',11) ON CONFLICT DO NOTHING;
INSERT INTO public_support (id,slug,title,summary,category,tags,heading,sections,related_articles,updated_at,environment,display_order) VALUES ('online-banking','online-banking','Using online banking safely','Digital banking access','DIGITAL_BANKING',ARRAY['digital banking access','guide']::text[],'Using online banking safely','[{"heading":"What to know","paragraphs":["Use trusted devices and keep browser and operating system updates current.","Sign out on shared devices and verify the site address before entering credentials. Avoid entering real credentials into a demo."],"callouts":["A public product guide never needs your banking password."]}]'::jsonb,ARRAY['account-statements','contact-support']::text[],'2026-09-27T09:00:00+08:00','DEMO',12) ON CONFLICT DO NOTHING;
INSERT INTO public_support (id,slug,title,summary,category,tags,heading,sections,related_articles,updated_at,environment,display_order) VALUES ('account-statements','account-statements','Reading an account statement','Statements guide','ACCOUNTS',ARRAY['statements guide','guide']::text[],'Reading an account statement','[{"heading":"What to know","paragraphs":["A statement summarises booked activity during a stated period.","Check opening and closing balances, transaction dates and fees. Report unfamiliar entries through a trusted support channel."],"callouts":["Pending authorisations may not appear as booked statement entries."]}]'::jsonb,ARRAY['contact-support','recognise-phishing']::text[],'2026-09-27T09:00:00+08:00','DEMO',13) ON CONFLICT DO NOTHING;
INSERT INTO public_support (id,slug,title,summary,category,tags,heading,sections,related_articles,updated_at,environment,display_order) VALUES ('contact-support','contact-support','Finding a trusted support channel','Contact and accessibility','DIGITAL_BANKING',ARRAY['contact and accessibility','guide']::text[],'Finding a trusted support channel','[{"heading":"What to know","paragraphs":["Use contact details from your verified bank app or official documentation.","Avoid numbers provided in suspicious messages. Ask your provider about accessible formats and communication options."],"callouts":["Aster is a demo and has no real customer contact centre."]}]'::jsonb,ARRAY['recognise-phishing','lost-card']::text[],'2026-09-27T09:00:00+08:00','DEMO',14) ON CONFLICT DO NOTHING;
